17	func (d *DB) CreateAttachment(ctx context.Context, create *store.Attachment) (*store.Attachment, error) {
18		fields := []string{"`uid`", "`filename`", "`blob`", "`type`", "`size`", "`creator_id`", "`memo_id`", "`storage_type`", "`reference`", "`payload`"}
19		placeholder := []string{"?", "?", "?", "?", "?", "?", "?", "?", "?", "?"}
20		storageType := ""
21		if create.StorageType != storepb.AttachmentStorageType_ATTACHMENT_STORAGE_TYPE_UNSPECIFIED {
22			storageType = create.StorageType.String()
23		}
24		payloadString := "{}"
25		if create.Payload != nil {
26			bytes, err := protojson.Marshal(create.Payload)
27			if err != nil {
28				return nil, errors.Wrap(err, "failed to marshal attachment payload")
29			}
30			payloadString = string(bytes)
31		}
32		args := []any{create.UID, create.Filename, create.Blob, create.Type, create.Size, create.CreatorID, create.MemoID, storageType, create.Reference, payloadString}
33	
34		stmt := "INSERT INTO `attachment` (" + strings.Join(fields, ", ") + ") VALUES (" + strings.Join(placeholder, ", ") + ") RETURNING `id`, `created_ts`, `updated_ts`"
35		if err := d.db.QueryRowContext(ctx, stmt, args...).Scan(&create.ID, &create.CreatedTs, &create.UpdatedTs); err != nil {
36			return nil, err
37		}
38	
39		return create, nil
40	}
