42	func (d *DB) ListAttachments(ctx context.Context, find *store.FindAttachment) ([]*store.Attachment, error) {
43		where, args := []string{"1 = 1"}, []any{}
44	
45		if v := find.ID; v != nil {
46			where, args = append(where, "`attachment`.`id` = ?"), append(args, *v)
47		}
48		if v := find.UID; v != nil {
49			where, args = append(where, "`attachment`.`uid` = ?"), append(args, *v)
50		}
51		if v := find.CreatorID; v != nil {
52			where, args = append(where, "`attachment`.`creator_id` = ?"), append(args, *v)
53		}
54		if v := find.Filename; v != nil {
55			where, args = append(where, "`attachment`.`filename` = ?"), append(args, *v)
56		}
57		if v := find.FilenameSearch; v != nil {
58			where, args = append(where, "`attachment`.`filename` LIKE ?"), append(args, fmt.Sprintf("%%%s%%", *v))
59		}
60		if v := find.MemoID; v != nil {
61			where, args = append(where, "`attachment`.`memo_id` = ?"), append(args, *v)
62		}
63		if len(find.MemoIDList) > 0 {
64			placeholders := make([]string, 0, len(find.MemoIDList))
65			for range find.MemoIDList {
66				placeholders = append(placeholders, "?")
67			}
68			where = append(where, "`attachment`.`memo_id` IN ("+strings.Join(placeholders, ",")+")")
69			for _, id := range find.MemoIDList {
70				args = append(args, id)
71			}
72		}
73		if find.HasRelatedMemo {
74			where = append(where, "`attachment`.`memo_id` IS NOT NULL")
75		}
76		if find.StorageType != nil {
77			where, args = append(where, "`attachment`.`storage_type` = ?"), append(args, find.StorageType.String())
78		}
79	
80		if len(find.Filters) > 0 {
81			engine, err := filter.DefaultAttachmentEngine()
82			if err != nil {
83				return nil, errors.Wrap(err, "failed to get filter engine")
84			}
85			if err := filter.AppendConditions(ctx, engine, find.Filters, filter.DialectSQLite, &where, &args); err != nil {
86				return nil, errors.Wrap(err, "failed to append filter conditions")
87			}
88		}
89	
90		fields := []string{
91			"`attachment`.`id` AS `id`",
92			"`attachment`.`uid` AS `uid`",
93			"`attachment`.`filename` AS `filename`",
94			"`attachment`.`type` AS `type`",
95			"`attachment`.`size` AS `size`",
96			"`attachment`.`creator_id` AS `creator_id`",
97			"`attachment`.`created_ts` AS `created_ts`",
98			"`attachment`.`updated_ts` AS `updated_ts`",
99			"`attachment`.`memo_id` AS `memo_id`",
100			"`attachment`.`storage_type` AS `storage_type`",
101			"`attachment`.`reference` AS `reference`",
102			"`attachment`.`payload` AS `payload`",
103			"CASE WHEN `memo`.`uid` IS NOT NULL THEN `memo`.`uid` ELSE NULL END AS `memo_uid`",
104		}
105		if find.GetBlob {
106			fields = append(fields, "`attachment`.`blob` AS `blob`")
107		}
108	
109		query := "SELECT " + strings.Join(fields, ", ") + " FROM `attachment`" + " " +
110			"LEFT JOIN `memo` ON `attachment`.`memo_id` = `memo`.`id`" + " " +
111			"WHERE " + strings.Join(where, " AND ") + " " +
112			"ORDER BY `attachment`.`updated_ts` DESC"
113		if find.Limit != nil {
114			query = fmt.Sprintf("%s LIMIT %d", query, *find.Limit)
115			if find.Offset != nil {
116				query = fmt.Sprintf("%s OFFSET %d", query, *find.Offset)
117			}
118		}
119	
120		rows, err := d.db.QueryContext(ctx, query, args...)
121		if err != nil {
122			return nil, err
123		}
124		defer rows.Close()
125	
126		list := make([]*store.Attachment, 0)
127		for rows.Next() {
128			attachment := store.Attachment{}
129			var memoID sql.NullInt32
130			var storageType string
131			var payloadBytes []byte
132			dests := []any{
133				&attachment.ID,
134				&attachment.UID,
135				&attachment.Filename,
136				&attachment.Type,
137				&attachment.Size,
138				&attachment.CreatorID,
139				&attachment.CreatedTs,
140				&attachment.UpdatedTs,
141				&memoID,
142				&storageType,
143				&attachment.Reference,
144				&payloadBytes,
145				&attachment.MemoUID,
146			}
147			if find.GetBlob {
148				dests = append(dests, &attachment.Blob)
149			}
150			if err := rows.Scan(dests...); err != nil {
151				return nil, err
152			}
153	
154			if memoID.Valid {
155				attachment.MemoID = &memoID.Int32
156			}
157			attachment.StorageType = storepb.AttachmentStorageType(storepb.AttachmentStorageType_value[storageType])
158			payload := &storepb.AttachmentPayload{}
159			if err := protojsonUnmarshaler.Unmarshal(payloadBytes, payload); err != nil {
160				return nil, err
161			}
162			attachment.Payload = payload
163			list = append(list, &attachment)
164		}
165	
166		if err := rows.Err(); err != nil {
167			return nil, err
168		}
169	
170		return list, nil
171	}
