173	func (d *DB) UpdateAttachment(ctx context.Context, update *store.UpdateAttachment) error {
174		set, args := []string{}, []any{}
175	
176		if v := update.UID; v != nil {
177			set, args = append(set, "`uid` = ?"), append(args, *v)
178		}
179		if v := update.UpdatedTs; v != nil {
180			set, args = append(set, "`updated_ts` = ?"), append(args, *v)
181		}
182		if v := update.Filename; v != nil {
183			set, args = append(set, "`filename` = ?"), append(args, *v)
184		}
185		if v := update.MemoID; v != nil {
186			set, args = append(set, "`memo_id` = ?"), append(args, *v)
187		}
188		if v := update.Reference; v != nil {
189			set, args = append(set, "`reference` = ?"), append(args, *v)
190		}
191		if v := update.Payload; v != nil {
192			bytes, err := protojson.Marshal(v)
193			if err != nil {
194				return errors.Wrap(err, "failed to marshal attachment payload")
195			}
196			set, args = append(set, "`payload` = ?"), append(args, string(bytes))
197		}
198	
199		args = append(args, update.ID)
200		stmt := "UPDATE `attachment` SET " + strings.Join(set, ", ") + " WHERE `id` = ?"
